insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_2_v1'
from (values
('127.16.d.1.A',2,'An internship in occupational safety helps a student by:','["giving real experience applying safety skills", "guaranteeing a promotion", "replacing all classes", "removing the need to learn"]'::jsonb,0,'Internships build practical skills.','original'),
('127.16.d.1.A',2,'Starting a safety consulting business is an example of:','["an unpaid chore", "an entrepreneurship opportunity in the field", "a required class", "a school holiday"]'::jsonb,1,'Entrepreneurs create businesses that meet needs.','original'),
('127.16.d.1.B',3,'A safety technician who earns more training and takes on supervision is showing:','["a pay cut", "a job freeze", "career advancement", "career loss"]'::jsonb,2,'Advancement means moving to higher roles.','original'),
('127.16.d.1.B',3,'One way to advance in a safety career is to:','["hide mistakes", "avoid learning", "skip training", "earn additional certifications and experience"]'::jsonb,3,'Credentials open higher positions.','original'),
('127.16.d.1.C',3,'A Certified Safety Professional credential generally requires:','["a combination of education, experience and passing an exam", "only a signature", "only a purchase", "no preparation"]'::jsonb,0,'Professional credentials have set requirements.','original'),
('127.16.d.1.C',3,'Professional credentials help safety workers by:','["avoiding laws", "showing they meet recognized standards", "ending the need for training", "replacing all experience"]'::jsonb,1,'Credentials demonstrate competence.','original'),
('127.16.d.2.A',2,'Under workplace safety laws, an employer is responsible for:','["paying for workers'' hobbies", "choosing workers'' friends", "providing a workplace free from recognized hazards", "ignoring injuries"]'::jsonb,2,'Employers must provide safe conditions.','original'),
('127.16.d.2.A',2,'A worker''s responsibility for safety includes:','["ignoring warnings", "hiding injuries", "removing guards", "following safety rules and reporting hazards"]'::jsonb,3,'Workers share safety duties.','original'),
('127.16.d.2.B',3,'The OSHA general duty clause requires employers to:','["keep the workplace free of recognized serious hazards", "offer free meals", "reduce all taxes", "hire more managers"]'::jsonb,0,'It covers hazards not named in specific standards.','original'),
('127.16.d.2.B',3,'A worker''s right to a safe workplace includes the right to:','["skip all duties", "report hazards without punishment", "avoid training", "set company policy"]'::jsonb,1,'Workers may raise safety concerns safely.','original'),
('127.16.d.2.C',3,'OSHA standards are important because they:','["decide pay rates", "assign vacations", "set minimum safety requirements for organizations", "replace job training"]'::jsonb,2,'Standards define required protections.','original'),
('127.16.d.2.C',3,'An organization that ignores OSHA standards risks:','["free equipment", "more holidays", "lower insurance only", "fines and unsafe conditions"]'::jsonb,3,'Noncompliance has consequences.','original'),
('127.16.d.2.D',3,'Industrial hygiene focuses on:','["recognizing and controlling workplace health hazards", "writing contracts", "scheduling shifts", "designing logos"]'::jsonb,0,'It protects worker health.','original'),
('127.16.d.2.D',3,'Which is a type of industrial hygiene hazard?','["parking layout", "chemical exposure", "break schedule", "office paint color"]'::jsonb,1,'Chemical, physical and biological hazards are studied.','original'),
('127.16.d.2.E',2,'Hearing protection is an example of:','["a work order", "a price tag", "personal protective equipment", "a time card"]'::jsonb,2,'PPE guards the worker''s body.','original'),
('127.16.d.2.E',2,'Safety goggles should be worn when:','["the room is quiet", "a task is finished", "a worker is on break", "there is a danger of flying particles or splashes"]'::jsonb,3,'Eye protection prevents injuries.','original'),
('127.16.d.2.F',2,'A safe walking surface should be:','["clean, dry and free of clutter", "cluttered with boxes", "covered in cords", "wet and slippery"]'::jsonb,0,'Good housekeeping prevents falls.','original'),
('127.16.d.2.F',2,'Slips and falls are reduced by:','["ignoring spills", "cleaning up spills right away", "waxing wet floors", "blocking aisles"]'::jsonb,1,'Quick cleanup removes hazards.','original'),
('127.16.d.2.G',3,'An electrical hazard in the workplace is:','["a labeled shelf", "a new tile floor", "a frayed power cord", "a clean desk"]'::jsonb,2,'Damaged cords can shock or start fires.','original'),
('127.16.d.2.G',3,'Working near overhead power lines risks:','["sunburn only", "hearing loss only", "paper cuts", "electrocution"]'::jsonb,3,'Contact with power lines can be fatal.','original'),
('127.16.d.2.H',3,'A control method that prevents electrical shock near water is a:','["ground-fault circuit interrupter", "loose plug", "extra extension cord", "wet glove"]'::jsonb,0,'GFCIs cut power when current leaks.','original'),
('127.16.d.2.H',3,'Before servicing equipment, a worker should use:','["a quick guess", "lockout/tagout procedures", "a louder radio", "a longer cord"]'::jsonb,1,'Lockout/tagout prevents accidental startup.','original'),
('127.16.d.2.I',3,'Hazardous materials should be stored:','["in open buckets", "in unmarked jars", "in labeled, approved containers", "near food"]'::jsonb,2,'Proper storage prevents leaks and mixing.','original'),
('127.16.d.2.I',3,'Transporting hazardous materials safely requires:','["speed over care", "no labels", "any container", "correct packaging, labeling and handling"]'::jsonb,3,'Rules protect handlers and the public.','original'),
('127.16.d.2.J',3,'One way to reduce exposure to a hazardous substance is to:','["use ventilation and protective equipment", "store it uncovered", "work without protection", "skip training"]'::jsonb,0,'Controls and PPE limit exposure.','original'),
('127.16.d.2.J',3,'Substituting a less toxic product for a more toxic one is an example of:','["increasing risk", "reducing exposure at the source", "adding hazards", "ignoring labels"]'::jsonb,1,'Substitution lowers the hazard.','original'),
('127.16.d.2.K',2,'Safety Data Sheets provide information about:','["a store''s hours", "a vehicle''s route", "a chemical''s hazards and safe handling", "a worker''s salary"]'::jsonb,2,'SDS describe chemical risks and precautions.','original'),
('127.16.d.2.K',2,'An emergency plan should tell workers:','["what to eat", "where to park", "when to take vacation", "how to evacuate and who to contact"]'::jsonb,3,'Plans guide safe responses.','original'),
('127.16.d.2.L',3,'A worker reads an SDS before using a new cleaner to decide:','["what protection and precautions are needed", "what color to wear", "when lunch is", "who will win a game"]'::jsonb,0,'SDS inform safety decisions.','original'),
('127.16.d.2.L',3,'Emergency plans help employers decide:','["when to hire interns", "how to respond during fires or spills", "how to cut taxes", "what to name a product"]'::jsonb,1,'Plans support quick, informed action.','original'),
('127.16.d.2.M',3,'A strong safety and health program includes:','["blame for every injury", "secret rules", "management leadership and worker participation", "no training"]'::jsonb,2,'Programs need leadership and involvement.','original'),
('127.16.d.2.M',3,'Worker participation in a safety program means employees:','["avoid reports", "wait to be told nothing", "make no suggestions", "help identify hazards and suggest improvements"]'::jsonb,3,'Workers know hazards best.','original'),
('127.16.d.2.N',2,'A written emergency action plan is important because it:','["prepares everyone to act quickly and safely", "replaces training", "stops all emergencies", "is only for managers"]'::jsonb,0,'Plans reduce confusion in emergencies.','original'),
('127.16.d.2.N',2,'Fire protection plans are written to:','["decorate offices", "reduce the risk and harm of fires", "avoid inspections", "raise prices"]'::jsonb,1,'They prepare for fire events.','original'),
('127.16.d.2.O',3,'A key part of an emergency action plan is:','["a parking permit", "a dress code", "evacuation routes and assembly points", "a menu"]'::jsonb,2,'Routes and assembly points save lives.','original'),
('127.16.d.2.O',3,'An emergency plan should name:','["only vendors", "no one", "only customers", "who is responsible for specific duties"]'::jsonb,3,'Assigned roles prevent delays.','original'),
('127.16.d.2.P',3,'A hazard communication program includes:','["labels, safety data sheets and employee training", "only advertisements", "only passwords", "only schedules"]'::jsonb,0,'Workers must know chemical hazards.','original'),
('127.16.d.2.P',3,'The purpose of hazard communication is to:','["advertise products", "inform workers about chemical hazards", "avoid inspections", "reduce paperwork forever"]'::jsonb,1,'Information protects workers.','original'),
('127.16.d.2.Q',3,'A safety training requirement set by a standards organization is:','["optional lessons only", "one-time lectures for managers only", "training before using certain equipment", "no instruction"]'::jsonb,2,'Standards require training for certain tasks.','original'),
('127.16.d.2.Q',3,'Training in forklift operation is required to:','["reduce cleanliness", "increase speed only", "avoid licenses", "help prevent accidents involving powered trucks"]'::jsonb,3,'Training protects operators and others.','original'),
('127.16.d.3.A',2,'One objective of the U.S. Environmental Protection Agency is to:','["protect human health and the environment", "print currency", "set sports schedules", "control school menus"]'::jsonb,0,'The EPA protects people and nature.','original'),
('127.16.d.3.A',2,'The EPA writes and enforces regulations about:','["movie ratings", "air, water and waste", "fashion trends", "team rosters"]'::jsonb,1,'Environmental laws cover pollution and waste.','original'),
('127.16.d.3.B',2,'The Texas Commission on Environmental Quality works to:','["manage school buses", "run state lotteries", "protect Texas'' environment and natural resources", "set tax rates"]'::jsonb,2,'TCEQ regulates environmental quality in Texas.','original'),
('127.16.d.3.B',2,'TCEQ regulates which of these in Texas?','["highway speeds only", "library hours", "college sports", "air and water quality"]'::jsonb,3,'TCEQ monitors environmental permits.','original'),
('127.16.d.3.C',3,'Agencies check compliance with environmental rules through:','["inspections and reporting", "guessing", "rumors", "advertising"]'::jsonb,0,'Monitoring uncovers violations.','original'),
('127.16.d.3.C',3,'A company that violates environmental rules may face:','["free permits", "fines and required cleanup", "tax credits automatically", "public praise"]'::jsonb,1,'Enforcement includes penalties.','original'),
('127.16.d.3.D',3,'The Endangered Species Act is intended to:','["build highways", "remove protections", "protect threatened and endangered species", "increase hunting"]'::jsonb,2,'The ESA protects species and habitat.','original'),
('127.16.d.3.D',3,'The Safe Drinking Water Act sets standards for:','["bottled soda labels", "restaurant menus", "swimming pool fees", "public drinking water quality"]'::jsonb,3,'It protects drinking water supplies.','original'),
('127.16.d.4.A',3,'Regular workplace inspections help control hazards by:','["finding problems before someone is hurt", "wasting time", "delaying production forever", "hiding hazards"]'::jsonb,0,'Inspections catch hazards early.','original'),
('127.16.d.4.A',3,'An effective inspection includes:','["a quick glance only", "a checklist and follow-up on findings", "no records", "ignoring defects"]'::jsonb,1,'Follow-up fixes the hazards found.','original'),
('127.16.d.4.B',2,'A worker who notices a hazard should:','["wait a week", "ignore it", "tell a supervisor right away", "post about it elsewhere"]'::jsonb,2,'Prompt reporting prevents harm.','original'),
('127.16.d.4.B',2,'After an accident, the worker should first:','["go home without telling", "blame someone", "delete the details", "report it to the immediate supervisor"]'::jsonb,3,'Reporting starts the response.','original'),
('127.16.d.4.C',2,'Safety training programs help by:','["building awareness of policies and procedures", "hiding rules", "increasing accidents", "avoiding tools"]'::jsonb,0,'Training promotes safe habits.','original'),
('127.16.d.4.C',2,'Employees are more likely to follow safety rules when they:','["are punished randomly", "understand why the rules exist", "are never trained", "hear them once"]'::jsonb,1,'Understanding improves compliance.','original'),
('127.16.d.4.D',2,'For tasks that splash chemicals, a worker should select:','["a baseball cap only", "sandals", "goggles, a face shield and gloves", "earbuds"]'::jsonb,2,'Match PPE to the hazard.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
